int set_color_map(struct fb_cmap *cmap, struct fb_info *info)
{
    int i, ret = 0;
    unsigned int dac_width = info->var.bits_per_pixel;

    if (dac_width == 8) {
        u16 *red = kmalloc(cmap->len * sizeof(u16), GFP_KERNEL);
        u16 *green = kmalloc(cmap->len * sizeof(u16), GFP_KERNEL);
        u16 *blue = kmalloc(cmap->len * sizeof(u16), GFP_KERNEL);
        u16 *transp = kmalloc(cmap->len * sizeof(u16), GFP_KERNEL);

        if (!red || !green || !blue || !transp) {
            ret = -ENOMEM;
            goto out;
        }

        for (i = 0; i < cmap->len; i++) {
            red[i] = cmap->red[i] >> (16 - dac_width);
            green[i] = cmap->green[i] >> (16 - dac_width);
            blue[i] = cmap->blue[i] >> (16 - dac_width);
            transp[i] = cmap->transp[i] >> (16 - dac_width);
        }

        ret = uvesafb_setpalette(cmap->start, cmap->len, red, green, blue, transp, info);
        kfree(red);
        kfree(green);
        kfree(blue);
        kfree(transp);
    } else {
        for (i = 0; i < cmap->len; i++) {
            ret = uvesafb_setcolreg(cmap->start + i, cmap->red[i], cmap->green[i],
                                    cmap->blue[i], cmap->transp[i], info);
            if (ret < 0)
                break;
        }
    }

out:
    return ret;
}

int set_color_map(struct fb_cmap *cmap, struct fb_info *info)
{
    int i;
    int ret = 0;

    if (info->var.bits_per_pixel > 8) {
        for (i = 0; i < cmap->len; i++) {
            ret = uvesafb_setcolreg(
                cmap->start + i,
                cmap->red[i], cmap->green[i], cmap->blue[i],
                cmap->transp[i], info
            );
            if (ret)
                break;
        }
        return ret;
    }

    if (cmap->start + cmap->len > 256) {
        return -EINVAL;
    }

    unsigned char *palette = kmalloc(cmap->len * 4, GFP_KERNEL);
    if (!palette)
        return -ENOMEM;

    for (i = 0; i < cmap->len; i++) {
        unsigned int r = cmap->red[i] >> (8 - info->dac_width);
        unsigned int g = cmap->green[i] >> (8 - info->dac_width);
        unsigned int b = cmap->blue[i] >> (8 - info->dac_width);

        palette[i * 4] = r;
        palette[i * 4 + 1] = g;
        palette[i * 4 + 2] = b;
        palette[i * 4 + 3] = cmap->transp[i];
    }

    ret = uvesafb_setpalette(cmap->start, cmap->len, palette, info);

    kfree(palette);

    return ret;
}

#include <stdlib.h>

int set_color_map(struct fb_cmap *cmap, struct fb_info *info) {
    int i;
    unsigned char *palette;

    if (info->var.bits_per_pixel > 8) {
        for (i = 0; i < cmap->length; i++) {
            uvesafb_setcolreg(i + cmap->start, cmap->red[i], cmap->green[i], cmap->blue[i], 0, info);
        }
        return 0;
    }

    if (cmap->start + cmap->length > 256) {
        return -EINVAL;
    }

    palette = malloc(cmap->length * 3);
    if (!palette) {
        return -ENOMEM;
    }

    for (i = 0; i < cmap->length; i++) {
        palette[3 * i] = cmap->red[i] >> (8 - info->dac_width);
        palette[3 * i + 1] = cmap->green[i] >> (8 - info->dac_width);
        palette[3 * i + 2] = cmap->blue[i] >> (8 - info->dac_width);
    }

    uvesafb_setpalette(cmap->start, cmap->length, palette, 0, info);

    free(palette);
    return 0;
}

int set_fb_colormap(struct fb_cmap *cmap, struct fb_info *info)
{
    int i, err;
    u16 *red, *green, *blue, *transp;

    if (info->var.bits_per_pixel <= 8) {
        if (cmap->start + cmap->len > 256)
            return -EINVAL;

        red = kmalloc_array(cmap->len, sizeof(u16), GFP_KERNEL);
        green = kmalloc_array(cmap->len, sizeof(u16), GFP_KERNEL);
        blue = kmalloc_array(cmap->len, sizeof(u16), GFP_KERNEL);
        transp = kmalloc_array(cmap->len, sizeof(u16), GFP_KERNEL);
        if (!red || !green || !blue || !transp) {
            err = -ENOMEM;
            goto fail_alloc;
        }

        for (i = 0; i < cmap->len; i++) {
            red[i] = cmap->red[i] >> (16 - info->dac_width);
            green[i] = cmap->green[i] >> (16 - info->dac_width);
            blue[i] = cmap->blue[i] >> (16 - info->dac_width);
            transp[i] = cmap->transp[i];
        }

        err = uvesafb_setpalette(cmap->start, cmap->len, red, green, blue, transp, info);
        if (err)
            goto fail_palette;

        return 0;

    fail_palette:
    fail_alloc:
        kfree(red);
        kfree(green);
        kfree(blue);
        kfree(transp);
        return err;
    } else {
        for (i = 0; i < cmap->len; i++) {
            err = uvesafb_setcolreg(cmap->start + i, cmap->red[i], cmap->green[i],
                                    cmap->blue[i], cmap->transp[i], info);
            if (err)
                return err;
        }
        return 0;
    }
}

int uvesafb_set_cmap(struct fb_cmap *cmap, struct fb_info *info)
{
    int i, err = 0;
    u16 *red, *green, *blue, *transp;

    if (info->var.bits_per_pixel <= 8) {
        if (cmap->start + cmap->len > 256)
            return -EINVAL;

        red = kmalloc_array(cmap->len, sizeof(u16), GFP_KERNEL);
        green = kmalloc_array(cmap->len, sizeof(u16), GFP_KERNEL);
        blue = kmalloc_array(cmap->len, sizeof(u16), GFP_KERNEL);
        transp = kmalloc_array(cmap->len, sizeof(u16), GFP_KERNEL);
        if (!red || !green || !blue || !transp) {
            err = -ENOMEM;
            goto out;
        }

        for (i = 0; i < cmap->len; i++) {
            red[i] = cmap->red[i] >> (16 - info->var.red.length);
            green[i] = cmap->green[i] >> (16 - info->var.green.length);
            blue[i] = cmap->blue[i] >> (16 - info->var.blue.length);
            transp[i] = cmap->transp[i] >> (16 - info->var.transp.length);
        }

        err = uvesafb_setpalette(cmap->start, cmap->len,
                                 red, green, blue, transp, info);
        if (err)
            goto out;

        kfree(red);
        kfree(green);
        kfree(blue);
        kfree(transp);
    } else {
        for (i = 0; i < cmap->len; i++) {
            err = uvesafb_setcolreg(
                cmap->start + i, cmap->red[i], cmap->green[i], cmap->blue[i],
                cmap->transp[i], info);
            if (err)
                break;
        }
    }

out:
    return err;
}
